def main():
    ok = True

    # ---- 1. join_frontmatter ↔ split_frontmatter 往返（最高代价失效的守门）----
    fm = 'summary: "含冒号：的摘要"\ntags: [a, b]\n'
    body = "# 标题\n正文首行\n"
    txt = K.join_frontmatter(fm, body)
    got_fm, got_body = K.split_frontmatter(txt)
    parsed_ok = False
    try:
        import yaml
        parsed_ok = isinstance(yaml.safe_load(got_fm), dict)
    except Exception:
        parsed_ok = False
    good = (got_fm != "" and parsed_ok and got_body.startswith("# 标题"))
    print(f"  [{'ok' if good else 'FAIL'}] join→split 往返可读出 frontmatter")
    ok = ok and good

    # 🔴 夹具：开围栏 `---` 后必须有换行（旧 qc_fix_yaml 的坏形态）
    bad = "---summary: \"x\"\n---\n# t\n"
    got_fm_bad, _ = K.split_frontmatter(bad)
    bad_detected = got_fm_bad == ""
    print(f"  [{'ok' if bad_detected else 'FAIL'}] 🔴 夹具：`---summary:` 形态解析不出"
          f"（join_frontmatter 正是为消除它而生）")
    ok = ok and bad_detected

    # 🔴 夹具：闭合 `---` 后必须有换行（124 页事故形态）
    bad2 = "---\nsummary: \"x\"\n---# t\n"
    got_fm_bad2, _ = K.split_frontmatter(bad2)
    print(f"  [info] `---# t` 闭合形态 -> frontmatter="
          f"{'解析出' if got_fm_bad2 else '解析不出'}"
          f"（注：_FM_RE 允许 `---` 后行尾，主要防线是 join_frontmatter）")

    # 正例：join_frontmatter 必须产出规范的换行布局
    good_layout = txt.startswith("---\n") and "\n---\n" in txt
    print(f"  [{'ok' if good_layout else 'FAIL'}] 规范布局：`---\\n` 开头、`\\n---\\n` 闭合")
    ok = ok and good_layout

    # ---- 2. QC 工作目录解析 ----
    # 🔴 本脚本自称"底座自检"，就不该**产生副作用**：旧版调 `qc_work_dir(create=True)`
    #    会在库里建出 `.qc/`（一次"只读自检"把目录建了出来，且 kb_toolcheck 的
    #    写盘防呆并不监视 `.qc/` ⇒ 完全隐形）。改为**只解析不创建**，
    #    并用 `MATSCI_QC_DIR` 环境变量把解析规则本身测掉（kb_lib 支持该覆盖）。
    wd = K.qc_work_dir()
    inside_vault = os.path.abspath(wd).startswith(os.path.abspath(K.VAULT))
    not_archive = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if inside_vault else 'FAIL'}] qc_work_dir 在库内 -> {wd}")
    ok = ok and inside_vault
    print(f"  [{'ok' if not_archive else 'FAIL'}] 默认写盘目标不在 _archive（归档只进不出）")
    ok = ok and not_archive
    # 临时目录统一走 K.temp_dir()（可写 + 清理不抛），理由见文件头说明。
    with K.temp_dir(prefix="kb_selftest_") as _qd:
        _old = os.environ.get("MATSCI_QC_DIR")
        try:
            os.environ["MATSCI_QC_DIR"] = _qd
            override_ok = os.path.abspath(K.qc_work_dir(create=True)) == os.path.abspath(_qd)
            created_here = os.path.isdir(_qd)
        finally:
            if _old is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = _old
        print(f"  [{'ok' if override_ok and created_here else 'FAIL'}] "
              f"MATSCI_QC_DIR 覆盖生效且 create=True 落在覆盖目录（自检零副作用）")
        ok = ok and override_ok and created_here
    # qc_input 的契约是「**解析规则**」（优先新工作目录、回退归档），不是
    #   「某个具体真源文件在不在」——后者是库专属前提，全新空库（无 .qc/queue.json）
    #   会因此假 FAIL。旧版正例写成 `os.path.exists(qc_input("queue.json"))`，
    #   把「解析规则对」错判成「库里有 queue.json」，属于把缺省值当断言。
    #   改为：在隔离临时目录里钉住**行为**——存在则返回该路径、缺失则不误报。
    with K.temp_dir(prefix="kb_selftest_qc_") as _qid:
        _oldq = os.environ.get("MATSCI_QC_DIR")
        try:
            os.environ["MATSCI_QC_DIR"] = _qid
            made = os.path.join(_qid, "queue.json")
            open(made, "w", encoding="utf-8").write("{}")
            ok_hit = os.path.abspath(K.qc_input("queue.json")) == os.path.abspath(made)
            miss = K.qc_input("绝不存在的-xyz.json")
            ok_miss = not os.path.exists(miss)
        finally:
            if _oldq is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = _oldq
    print(f"  [{'ok' if ok_hit else 'FAIL'}] qc_input 正例：已存在文件解析到工作目录")
    print(f"  [{'ok' if ok_miss else 'FAIL'}] qc_input 反例：不存在文件不误报")
    ok = ok and ok_hit and ok_miss

    # ---- 3. read_text：CRLF/LF 混合（本库已知陷阱）----
    with tempfile.NamedTemporaryFile(delete=False, suffix=".md") as fh:
        fh.write(b"---\r\ntype: source\r\n---\r\nbody\r\n")
        crlf = fh.name
    with tempfile.NamedTemporaryFile(delete=False, suffix=".md") as fh:
        fh.write(b"---\ntype: source\n---\nbody\n")
        lf = fh.name
    a = K.read_text(crlf)
    b = K.read_text(lf)
    same = a == b and "\r" not in a
    print(f"  [{'ok' if same else 'FAIL'}] read_text 归一化换行（CRLF 与 LF 同结果）")
    ok = ok and same
    fm_crlf, body_crlf = K.split_frontmatter(a)
    good = fm_crlf != "" and "type: source" in fm_crlf and body_crlf.strip() == "body"
    print(f"  [{'ok' if good else 'FAIL'}] CRLF 文件的 frontmatter 不丢（本库静默失效陷阱）")
    ok = ok and good
    os.unlink(crlf)
    os.unlink(lf)

    # ---- 4. extract_outlinks：代码块内的 [[...]] 必须剔除 ----
    text = ("正文 [[concepts/固态电解质]]\n"
            "```\n[[concepts/示例文本]]\n```\n"
            "行内 `[[concepts/行内示例]]`\n")
    outs = K.extract_outlinks(text)
    real = [x for x in outs if "固态电解质" in x]
    fake = [x for x in outs if "示例" in x]
    good = len(real) == 1 and len(fake) == 0
    print(f"  [{'ok' if good else 'FAIL'}] extract_outlinks 剔除代码块示例 "
          f"(真={len(real)} 假={len(fake)})")
    ok = ok and good

    # ---- 4b. parse_budget / parse_layers：单一实现的行为必须与三份旧拷贝逐一等价 ----
    #      收敛动机：这三份拷贝分别在 kb.py / kb_route.py / kb_serve.py 里，
    #      同源代码必然漂移。夹具把**旧实现**写死在这里做反算，一旦新实现改变语义立刻 FAIL。
    def _old_budget(s):
        if not s:
            return None
        parts = [int(x) for x in s.split(",") if x.strip()]
        return {f"L{i + 1}": v for i, v in enumerate(parts[:3])}

    def _old_layers(s):
        return (tuple(int(x) for x in s.split(",") if x.strip()) if s
                else (1, 2, 3))

    _pcases = ["", "5,5,8", "3", "1,2,3,4,5", "10,20", " 4 , 5 ", None]
    _bdiff = [c for c in _pcases if _old_budget(c) != K.parse_budget(c)]
    _ldiff = [c for c in _pcases if _old_layers(c) != K.parse_layers(c)]
    good = not _bdiff and not _ldiff
    print(f"  [{'ok' if good else 'FAIL'}] parse_budget/parse_layers 与旧拷贝逐一等价"
          f"（预算差异 {len(_bdiff)}、分层差异 {len(_ldiff)}）")
    ok = ok and good
    # 反例：必须真的会区分，不能是"两边都返回同一种错值"的恒真夹具
    _rev = (K.parse_budget("") is None and K.parse_budget("5,5,8") == {"L1": 5, "L2": 5, "L3": 8}
            and K.parse_layers("1,2") == (1, 2) and K.parse_layers(None) == (1, 2, 3)
            and K.parse_budget("1,2,3,4") == {"L1": 1, "L2": 2, "L3": 3})
    print(f"  [{'ok' if _rev else 'FAIL'}] 反例：解析结果的具体取值正确（非恒真夹具）")
    ok = ok and _rev

    # ---- 4c. 写盘三件套（backup_file / write_text_verified / detect_eol）----
    #      这三条是 CLAUDE.md §写盘脚本的额外铁律的**唯一实现**，`lit_finish`、
    #      `kb_lint --deep --fix --apply` 与 `qc_*` 写盘工具都调它。
    #      最关键的两点是**备份必须保留相对结构**（否则同名页互相覆盖 = 没有备份）
    #      与**写后复算**（原先 kb_lint 的 docstring 声称做了、代码里没有）。
    import shutil as _sh
    import tempfile as _tf
    _wdir = None
    try:
        _wdir = K.make_temp_dir(prefix="kb_selftest_write_")
        _saved_vault = K.VAULT
        _saved_qcw = K.qc_work_dir
        K.VAULT = _wdir
        K.qc_work_dir = lambda create=False: os.path.join(_wdir, ".qc")
        os.makedirs(os.path.join(_wdir, "wiki", "sources"), exist_ok=True)
        os.makedirs(os.path.join(_wdir, "wiki", "concepts"), exist_ok=True)
        _a = os.path.join(_wdir, "wiki", "sources", "同名.md")
        _b = os.path.join(_wdir, "wiki", "concepts", "同名.md")
        for _p, _t in ((_a, "source"), (_b, "concept")):
            with open(_p, "w", encoding="utf-8") as _f:
                _f.write(f"---\ntype: {_t}\n---\ntext-{_t}\n")
        _ba, _bb = K.backup_file(_a), K.backup_file(_b)
        good = bool(_ba and _bb and _ba != _bb
                    and open(_ba, encoding="utf-8").read().endswith("text-source\n")
                    and open(_bb, encoding="utf-8").read().endswith("text-concept\n"))
        print(f"  [{'ok' if good else 'FAIL'}] backup_file 保留相对结构（同名页不互相覆盖）")
        ok = ok and good

        _ok1, _d1 = K.write_text_verified(_a, "---\ntype: source\n---\nnew\n")
        _ok2, _d2 = K.write_text_verified(_a, "no frontmatter\n")
        good = _ok1 and (not _ok2) and "frontmatter" in _d2
        print(f"  [{'ok' if good else 'FAIL'}] write_text_verified 正例通过 / 反例"
              f"（写坏 frontmatter）被拦（{_d2[:34]}）")
        ok = ok and good
        # 换行：CRLF 必须写回 CRLF；平局取 LF
        _c = os.path.join(_wdir, "wiki", "concepts", "crlf.md")
        with open(_c, "wb") as _f:
            _f.write(b"---\r\ntype: concept\r\n---\r\nbody\r\n")
        K.write_text_keep_eol(_c, "---\ntype: concept\n---\nnew\n")
        _raw = open(_c, "rb").read()
        good = _raw.count(b"\r\n") == 4 and _raw.count(b"\n") == 4
        print(f"  [{'ok' if good else 'FAIL'}] write_text_keep_eol 保住 CRLF"
              f"（crlf={_raw.count(b'\r\n')} bare={_raw.count(b'\n') - _raw.count(b'\r\n')}）")
        ok = ok and good
        _tie = os.path.join(_wdir, "wiki", "concepts", "tie.md")
        with open(_tie, "wb") as _f:
            _f.write(b"a\r\nb\r\nc\nd\n")
        _e, _m = K.detect_eol(_tie)
        good = (_m is True) and (_e == "\n")
        print(f"  [{'ok' if good else 'FAIL'}] detect_eol 识别混合且平局取 LF（{_e!r} mixed={_m}）")
        ok = ok and good
    finally:
        if _wdir:
            try:
                K.VAULT = _saved_vault
                K.qc_work_dir = _saved_qcw
            except NameError:
                pass
            _sh.rmtree(_wdir, ignore_errors=True)

    # ---- 5. 页面集合与索引一致（同源口径）----
    # ⚠️ 这一项依赖**派生数据**（wiki/.index/meta_full.json），索引没重建就会不对称。
    #    它此前计入 `ok` ⇒ 底座自检会因为"索引还没刷新"而 FAIL，而那不是代码缺陷
    #    （CLAUDE.md §校验器自检纪律 明确点名这类"自检断言当前状态"的腐坏）。
    #    ⇒ 降为 WARN：报出来，但不否定整轮自检。
    names = set()
    # 🔴 索引口径包含项目卡（kb_build_index.scan_pages 用 include_projects=True）；
    #    这里若只数 wiki 页，165 张项目卡会被误报成「索引多出来的幽灵页」。
    for rel in K.iter_page_files(include_projects=True):
        names.add(os.path.basename(rel)[:-3])
    full = os.path.join(K.INDEX_DIR, "meta_full.json")
    if os.path.exists(full):
        import json
        with open(full, encoding="utf-8") as fh:
            mp = set(json.load(fh).get("pages", {}).keys())
        diff = len(names ^ mp)
        print(f"  [{'ok' if diff == 0 else 'WARN'}] 页面集合 vs 索引 对称差={diff}"
              f"（页 {len(names)} / 索引 {len(mp)}）"
              + ("" if diff == 0 else "  ← 跑 kb_build_index.py 刷新，非代码缺陷"))
    else:
        print("  [info] meta_full.json 不存在，跳过索引一致性检查")

    ok = check_type_dir(ok) and ok
    ok = check_dual_parser(ok) and ok
    ok = check_page_fm_sidecar(ok) and ok
    ok = check_temp_dir_helper(ok) and ok

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


if __name__ == "__main__":
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/kb_selftest.py   # 运行 kb_lib 底座自检")
        print("\n用法: python tools/kb_selftest.py   # 无参数即运行全部底座自检")
        sys.exit(0)
    sys.exit(main())
